        /// <summary>{{n.Words}} repository'si. Ortak işlemler <see cref="IRepository{TEntity, TId}"/>'de; özel sorguları buraya ekle.</summary>
        public interface I{{n.Entity}}Repository : IRepository<{{n.Entity}}, {{n.IdType}}>;

        """;

    public static string Repository(CrudNames n) => $$"""
        {{Header}}
        using Can.Core.Persistence.Repositories;
        using {{n.Root}}.Application.Services.Repositories;
        using {{n.Root}}.Persistence.Contexts;
        using {{n.Model.Namespace}};

        namespace {{n.Root}}.Persistence.Repositories;

        public sealed class {{n.Entity}}Repository : EfRepository<{{n.Entity}}, {{n.IdType}}>, I{{n.Entity}}Repository
        {
            public {{n.Entity}}Repository(BaseDbContext context)
                : base(context) { }
        }

        """;

    // ------------------------------------------------------------------ Persistence

    public static string Configuration(CrudNames n)
    {
        var lines = new List<string> { $"builder.ToTable(\"{n.Plural}\", Schemas.App).HasKey(x => x.Id);", $"builder.Property(x => x.Id).HasColumnName(\"Id\");" };
        foreach (EntityProperty property in n.Model.Properties.Where(p => p.Name != "Id"))
        {
            string? max = n.Model.MaxLengthConstant(property.Name);
            string column = $".HasColumnName(\"{property.Name}\")";
            switch (property.Kind)
            {
                case PropertyKind.Scalar when property.IsString:
                    string required = property.IsNullable ? string.Empty : ".IsRequired()";
                    lines.Add(max is not null
                        ? $"builder.Property(x => x.{property.Name}){column}.HasMaxLength({n.Entity}.{max}){required};"
                        : $"builder.Property(x => x.{property.Name}){column}{required}; // TODO(can-gen): Uzunluk sınırı ver: .HasMaxLength(...)");
                    break;
                case PropertyKind.Scalar when property.BareType is "decimal" or "Decimal":
                    lines.Add($"builder.Property(x => x.{property.Name}){column}.HasPrecision(18, 2); // TODO(can-gen): Hassasiyeti kontrol et.");
                    break;
                case PropertyKind.Scalar:
                    lines.Add($"builder.Property(x => x.{property.Name}){column};");
                    break;
                case PropertyKind.Enum:
                    lines.Add($"builder.Property(x => x.{property.Name}){column}.HasConversion<string>().HasMaxLength(32);");
                    break;
                case PropertyKind.Collection:
                    lines.Add($"// TODO(can-gen): {property.Name} koleksiyonunu eşle: builder.HasMany(x => x.{property.Name}).WithOne().HasForeignKey(\"{n.Entity}Id\");");
                    break;
                case PropertyKind.Complex:
                    lines.Add($"// TODO(can-gen): {property.Name} ({property.BareType}) için eşleme yaz: value object ise builder.OwnsOne(x => x.{property.Name}), entity ise ilişki (HasOne).");
                    break;
            }
        }

        lines.Add("// TODO(can-gen): Index ve ilişkileri ekle, ör. builder.HasIndex(x => x.Name, \"UK_" + n.Plural + "_Name\").IsUnique();");
        string body = string.Join("\n", lines.Select(l => "        " + l));

        return $$"""
            {{Header}}
            using Microsoft.EntityFrameworkCore;
            using Microsoft.EntityFrameworkCore.Metadata.Builders;
            using {{n.Root}}.Persistence.Contexts;
            using {{n.Model.Namespace}};

            namespace {{n.Root}}.Persistence.EntityConfigurations;

            public sealed class {{n.Entity}}Configuration : IEntityTypeConfiguration<{{n.Entity}}>
            {
                public void Configure(EntityTypeBuilder<{{n.Entity}}> builder)
                {
            {{body}}
                }
            }

            """;
    }

    // ------------------------------------------------------------------ WebAPI

    public static string Controller(CrudNames n)
    {
        string E = n.Entity;
        string P = n.Plural;
        string c = Names.Camel(E);
        return $$"""
            {{Header}}
            using Can.Core.Application.Requests;
            using Can.Core.Application.Responses;
            using Can.Core.Persistence.Dynamic;
            using Can.Core.WebApi.Controllers;
            using Microsoft.AspNetCore.Mvc;
            using {{n.FeatureNamespace}}.Commands.Create;
            using {{n.FeatureNamespace}}.Commands.Delete;
            using {{n.FeatureNamespace}}.Commands.Update;
            using {{n.FeatureNamespace}}.Queries.GetById;
            using {{n.FeatureNamespace}}.Queries.GetList;
            using {{n.FeatureNamespace}}.Queries.GetListByDynamic;

            namespace {{n.Root}}.WebAPI.Controllers;

            /// <summary><c>/api/v1/{{P}}</c>. Yetki handler'larda (<c>ISecuredRequest</c>, {{P}}OperationClaims) denetlenir.</summary>
            [Route("api/v1/[controller]")]
            [ApiController]
            public class {{P}}Controller : BaseController
            {
                [HttpPost]
                public async Task<IActionResult> Add([FromBody] Create{{E}}Command create{{E}}Command, CancellationToken cancellationToken)
                {
                    Created{{E}}Response response = await Mediator.Send(create{{E}}Command, cancellationToken);
                    return Created(uri: $"api/v1/{{P}}/{response.Id}", response);
                }

                [HttpPut]
                public async Task<IActionResult> Update([FromBody] Update{{E}}Command update{{E}}Command, CancellationToken cancellationToken)
                {
                    Updated{{E}}Response response = await Mediator.Send(update{{E}}Command, cancellationToken);
                    return Ok(response);
                }

                [HttpDelete("{Id}")]
                public async Task<IActionResult> Delete([FromRoute] Delete{{E}}Command delete{{E}}Command, CancellationToken cancellationToken)
                {
                    Deleted{{E}}Response response = await Mediator.Send(delete{{E}}Command, cancellationToken);
                    return Ok(response);
                }

                [HttpGet("{Id}")]
                public async Task<IActionResult> GetById([FromRoute] GetById{{E}}Query getById{{E}}Query, CancellationToken cancellationToken)
                {
                    GetById{{E}}Response response = await Mediator.Send(getById{{E}}Query, cancellationToken);
                    return Ok(response);
                }

                [HttpGet]
                public async Task<IActionResult> GetList([FromQuery] PageRequest pageRequest, CancellationToken cancellationToken)
                {
                    GetList{{E}}Query getList{{E}}Query = new() { PageRequest = pageRequest };
                    GetListResponse<GetList{{E}}ListItemDto> response = await Mediator.Send(getList{{E}}Query, cancellationToken);
                    return Ok(response);
                }

                [HttpPost("GetList/ByDynamic")]
                public async Task<IActionResult> GetListByDynamic([FromQuery] PageRequest pageRequest, [FromBody] DynamicQuery? dynamicQuery, CancellationToken cancellationToken)
                {
                    GetListByDynamic{{E}}Query getListByDynamic{{E}}Query = new() { PageRequest = pageRequest, DynamicQuery = dynamicQuery };
                    GetListResponse<GetList{{E}}ListItemDto> response = await Mediator.Send(getListByDynamic{{E}}Query, cancellationToken);
                    return Ok(response);
                }
            }

            """;
    }

    // ------------------------------------------------------------------ yardımcılar

    /// <summary>Komutun özellikleri (model bağlama için get/set).</summary>
    private static string CommandProperties(IReadOnlyList<MethodParameter> fields) =>
        string.Join("\n\n", fields.Select(f => $"    public {f.Type} {f.Name} {{ get; set; }}{Initializer(f)}"));

    /// <summary>Nullable olmayan referans tiplere başlangıç değeri (nullable uyarısı hata sayılır).</summary>
    private static string Initializer(MethodParameter field) =>
        field.IsNullable ? string.Empty
        : field.IsString ? " = string.Empty;"
        : IsPrimitiveValueType(field.BareType) ? string.Empty
        : " = default!;"; // enum, struct ya da sınıf: hepsinde geçerli

    private static bool IsPrimitiveValueType(string type) =>
        type is "bool" or "Boolean" or "byte" or "short" or "int" or "long" or "float" or "double" or "decimal" or "char"
            or "Byte" or "Int16" or "Int32" or "Int64" or "Single" or "Double" or "Decimal"
            or "Guid" or "DateTime" or "DateTimeOffset" or "DateOnly" or "TimeOnly" or "TimeSpan";
}
